-- Examik — language exams (IELTS / TOEFL / Duolingo), plan Block 2 proof.
-- Run AFTER 04_qualifications.sql. This adds THREE new exams with ZERO app code:
-- one row each in `qualifications` + their section rows in `curriculum`. Once run,
-- the client (qualifications-store.jsx + curriculum-store.jsx) surfaces them in
-- the picker and builds a full section course — proving "exam without code".
-- Re-run-safe: deletes these ids first, so running twice never duplicates.

begin;

delete from public.qualifications where id in ('ielts','toefl','duolingo');
delete from public.curriculum     where qualification_id in ('ielts','toefl','duolingo');



commit;
